func builtinIMDbTop250Snapshot() *ChartSnapshot {
	entries := builtinIMDbTop250Entries()
	return &ChartSnapshot{
		Chart:     ChartIMDbTop250,
		Source:    SourceIMDbTop250Builtin,
		UpdatedAt: time.Now().UTC(),
		Count:     len(entries),
		Entries:   entries,
	}
}

